import { chromium } from 'playwright';
import fs from 'fs';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForLoadState('networkidle');
await p.goto('http://127.0.0.1:54569/integrations');
await p.waitForLoadState('networkidle');
await p.click('#gen');
await p.waitForSelector('#toast:not([hidden])');
const txt = await p.textContent('#toast');
console.log('TOAST:', txt);
const key = txt.split('(shown once): ')[1].trim();
fs.writeFileSync('key.txt', key);
await p.goto('http://127.0.0.1:54569/webhooks');
await p.waitForLoadState('networkidle');
console.log((await p.content()).replace(/^[\s\S]*?<body>/,''));
await b.close();
EOF
